mapper.insert:
INSERT INTO async_task (
    task_type, business_key, payload, priority, status,
    retry_count, max_retry, timeout_seconds, version
) VALUES (
    #{taskType}, #{businessKey}, #{payload}, #{priority}, #{status},
    #{retryCount}, #{maxRetry}, #{timeoutSeconds}, #{version}
)

INSERT INTO task_execution_log (
    task_id, execute_node, status, error_msg,
    execute_start_time, execute_end_time, duration_ms
) VALUES (
    #{taskId}, #{executeNode}, #{status}, #{errorMsg},
    #{executeStartTime}, #{executeEndTime}, #{durationMs}
)

mapper.select:
SELECT * FROM task_execution_log
WHERE task_id = #{taskId}
ORDER BY create_time DESC

mapper.update:
INSERT INTO task_statistics (
    task_type, stat_hour, total_count, success_count, failed_count, avg_duration_ms
) VALUES (
    #{taskType}, #{statHour}, #{totalCount}, #{successCount}, #{failedCount}, #{avgDurationMs}
)
ON DUPLICATE KEY UPDATE
    total_count = total_count + #{totalCount},
    success_count = success_count + #{successCount},
    failed_count = failed_count + #{failedCount},
    avg_duration_ms = (avg_duration_ms + #{avgDurationMs}) / 2

mapper.delete:
DELETE FROM async_task
WHERE status IN (2, 4)
  AND create_time < #{beforeTime}
LIMIT #{limit}

DELETE FROM task_execution_log
WHERE create_time < #{beforeTime}
LIMIT #{limit}
